mod audio;
// BIO program for the I2S mic, vendored verbatim from bio-sim (sw/i2s). Autogenerated -- do not edit.
mod i2s_bio;
#[cfg(feature = "mel")]
mod mel;
mod pins;
mod uart_out;

use audio::{ActiveAudio, AudioSource};
use uart_out::UartOut;

fn main() -> ! {
    log_server::init_wait().unwrap();
    log::set_max_level(log::LevelFilter::Info);
    log::info!("ear starting, PID {}", xous::process::id());

    let hal = bao1x_hal_service::Hal::new();
    hal.set_preemption(true);

    let mut audio    = ActiveAudio::new();
    let mut uart_out = UartOut::new();

    log::info!("ear ready");

    // With the `mel` feature: run the FFT + 24-band mel filterbank on each frame and
    // send framed MelFrames to the eye. Otherwise: the temporary level path - a simple
    // RMS from each frame sent as one 0-255 byte.
    #[cfg(feature = "mel")]
    let mut processor = mel::MelProcessor::new();

    loop {
        let frame = audio.read_frame();
        #[cfg(feature = "mel")]
        uart_out.send(&processor.process(&frame));
        #[cfg(not(feature = "mel"))]
        {
            let rms = (frame.iter().map(|&s| (s as f32 / 32768.0).powi(2)).sum::<f32>()
                / frame.len() as f32).sqrt();
            uart_out.send_level(rms * 1.8); // tune: higher = more sensitive
        }
    }
}
